// Render app
document.addEventListener('DOMContentLoaded', () => {
    const app = document.getElementById('app');
    app.innerHTML = App();

    // Add interactivity
    setupEventListeners();
});

// Event listeners for interactivity
function setupEventListeners() {
    // Add to cart buttons
    document.querySelectorAll('.add-to-cart').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const productTitle = e.target.closest('.product-card').querySelector('.product-title').textContent;
            showNotification(`${productTitle} added to cart!`);
        });
    });

    // Deal CTAs
    document.querySelectorAll('.deal-cta').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const dealTitle = e.target.closest('.deal-card').querySelector('.deal-title').textContent;
            showNotification(`Browsing ${dealTitle}...`);
        });
    });

    // Editorial links
    document.querySelectorAll('.read-more').forEach(link => {
        link.addEventListener('click', (e) => {
            e.preventDefault();
            const articleTitle = e.target.closest('.editorial-card').querySelector('.editorial-title').textContent;
            showNotification(`Reading: ${articleTitle}`);
        });
    });

    // CTA button
    document.querySelector('.cta-button').addEventListener('click', () => {
        showNotification('Opening collection...');
    });

    // Icon buttons
    document.querySelectorAll('.icon-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const label = e.target.getAttribute('aria-label');
            if (label === 'Shopping cart') {
                showNotification('Cart is empty');
            } else {
                showNotification(`${label} feature activated`);
            }
        });
    });
}

// Notification helper
function showNotification(message) {
    console.log(message);
    // Visual feedback can be added here
}
